record.field:
# Cleanup error logs older than retention period
retention_days = int(env['ir.config_parameter'].sudo().get_param('digital_twin.errors.retention_days', 30))
cutoff_date = fields.Datetime.now() - timedelta(days=retention_days)

orchestrators = env['bcm.data.collection.orchestrator'].search([])
for orchestrator in orchestrators:
    if orchestrator.error_log:
        # Keep only recent error entries
        error_lines = orchestrator.error_log.split('\n')
        recent_errors = []
        for line in error_lines:
            if line.strip() and '[' in line:
                try:
                    timestamp_str = line[1:20]  # Extract timestamp
                    error_date = datetime.strptime(timestamp_str, '%Y-%m-%dT%H:%M:%S')
                    if error_date >= cutoff_date:
                        recent_errors.append(line)
                except:
                    recent_errors.append(line)  # Keep malformed entries

        if len(recent_errors) != len(error_lines):
            orchestrator.error_log = '\n'.join(recent_errors)

# Perform health checks on all active orchestrators
orchestrators = env['bcm.data.collection.orchestrator'].search([
    ('collection_status', 'in', ['collecting', 'idle'])
])

for orchestrator in orchestrators:
    try:
        health_results = orchestrator.health_check_all_services()
        # Log health check results if needed
        if any(result.get('status') == 'error' for category in health_results.values()
               for result in category.values()):
            orchestrator._log_error(f"Health check found service issues: {health_results}")
    except Exception as e:
        orchestrator._log_error(f"Health check failed: {str(e)}")

# Update performance metrics for all orchestrators
orchestrators = env['bcm.data.collection.orchestrator'].search([])

for orchestrator in orchestrators:
    try:
        current_metrics = orchestrator.performance_metrics or {}

        # Calculate throughput metrics
        if orchestrator.collection_status == 'collecting':
            # Update collections per minute
            total_collections = current_metrics.get('total_collections', 0)
            if total_collections > 0:
                # Simple calculation based on recent activity
                current_metrics['throughput_metrics'] = {
                    'collections_per_minute': min(total_collections / 60, 60),  # Cap at 60/min
                    'data_points_per_second': min(total_collections / 3600, 10)  # Cap at 10/sec
                }

        current_metrics['last_updated'] = fields.Datetime.now().isoformat()
        orchestrator.performance_metrics = current_metrics

    except Exception as e:
        orchestrator._log_error(f"Performance metrics update failed: {str(e)}")
